import React from "react";

const Filters = ({ filters, setFilters, options }) => {
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFilters({ ...filters, [name]: value });
  };

  return (
    <div style={{ display: "flex", gap: "20px" }}>
      <div>
        <label>Crime Type:</label>
        <select name="CrimeCode" onChange={handleChange} value={filters.CrimeCode || ""}>
          <option value="">All</option>
          {options.CrimeCode?.map((c) => (
            <option key={c} value={c}>{c}</option>
          ))}
        </select>
      </div>

      <div>
        <label>District:</label>
        <select name="District" onChange={handleChange} value={filters.District || ""}>
          <option value="">All</option>
          {options.District?.map((d) => (
            <option key={d} value={d}>{d}</option>
          ))}
        </select>
      </div>

      <div>
        <label>Neighborhood:</label>
        <select name="Neighborhood" onChange={handleChange} value={filters.Neighborhood || ""}>
          <option value="">All</option>
          {options.Neighborhood?.map((n) => (
            <option key={n} value={n}>{n}</option>
          ))}
        </select>
      </div>
    </div>
  );
};

export default Filters;
